import {Pressable,Text,View} from "react-native";
import {joinClasses} from "@/components/nyc-tron/ui/components/styles";

/**
 * Labeled on/off row shared by the canvas settings panels: a 44pt switch with
 * the label on the start side and the track on the end side (mirrored in RTL).
 */
export function SettingSwitch({label,on,onChange,disabled,styled,hint}:{
  label:string;on:boolean;onChange:(on:boolean)=>void;disabled:boolean;styled:boolean;hint?:string|undefined;
}){
  return <Pressable role="switch" aria-checked={on} accessibilityRole="switch" accessibilityState={{checked:on,disabled}}
    aria-label={label} accessibilityHint={hint} disabled={disabled} onPress={()=>onChange(!on)}
    {...{className:joinClasses(styled&&"rounded-control focus-visible:ring-2 focus-visible:ring-focus")}}
    style={{minHeight:44,flexDirection:"row",alignItems:"center",justifyContent:"space-between",gap:12,paddingHorizontal:4,opacity:disabled?0.5:1}}>
    <Text {...{className:joinClasses(styled&&"text-text text-sm")}} style={{flexShrink:1}}>{label}</Text>
    <View pointerEvents="none" {...{className:joinClasses(styled&&"border",styled&&(on?"bg-primary border-primary":"bg-surface-sunken border-border"))}}
      style={{width:40,height:24,borderRadius:12,padding:2,justifyContent:"center",alignItems:on?"flex-end":"flex-start"}}>
      <View {...{className:joinClasses(styled&&(on?"bg-on-primary":"bg-text-muted"))}} style={{width:18,height:18,borderRadius:9}}/>
    </View>
  </Pressable>;
}

import {View,type ViewProps} from 'react-native';
import {Select} from '@/components/nyc-tron/ui/components/Select';
import {UnitInput} from '@/components/nyc-tron/ui/components/shell/UnitInput';
import {SettingSwitch} from '@/components/nyc-tron/ui/components/forge/canvas/SettingSwitch';
import {validateLens,type LensSettings} from '@/components/nyc-tron/ui/components/forge/photo/photo-adjustments';
export type {LensSettings} from '@/components/nyc-tron/ui/components/forge/photo/photo-adjustments';
export interface LensProfile {readonly id:string;readonly label:string}
export interface LensCorrectionPanelProps extends Omit<ViewProps,'children'> {readonly value:LensSettings;readonly profiles:readonly LensProfile[];readonly onCommit:(value:LensSettings)=>void;readonly disabled?:boolean;readonly unstyled?:boolean}
/** Host-supplied calibrated profile identity and manual distortion/CA intent. */
export function LensCorrectionPanel({value,profiles,onCommit,disabled=false,unstyled=false,...props}:LensCorrectionPanelProps){
 validateLens(value);
 const ids=new Set<string>();for(const p of profiles){if(!p.id.trim()||!p.label.trim()||ids.has(p.id))throw new TypeError('Lens profiles require unique nonempty identities and labels');ids.add(p.id);}
 const set=(change:Partial<LensSettings>)=>{if(disabled)return;const next={...value,...change};validateLens(next);onCommit(next);};
 const options=[{value:'',label:'Manual correction'},...profiles.map(p=>({value:p.id,label:p.label}))];
 if(value.profileId!==null&&!ids.has(value.profileId))options.push({value:value.profileId,label:`Unavailable profile: ${value.profileId}`});
 return <View {...props} style={[{gap:8},props.style]}>
  <SettingSwitch label="Enable lens corrections" on={value.enabled} onChange={enabled=>set({enabled})} disabled={disabled} styled={!unstyled}/>
  <Select label="Lens correction profile" value={value.profileId??''} options={options} disabled={disabled||!value.enabled} unstyled={unstyled} onValueChange={id=>set({profileId:id||null})}/>
  <UnitInput label="Lens distortion" value={value.distortion} min={-100} max={100} step={1} disabled={disabled||!value.enabled} unstyled={unstyled} onCommit={distortion=>{if(distortion!==value.distortion)set({distortion});}}/>
  <SettingSwitch label="Remove chromatic aberration" on={value.chromaticAberration} onChange={chromaticAberration=>set({chromaticAberration})} disabled={disabled||!value.enabled} styled={!unstyled}/>
 </View>;
}

/**
 * Tailwind classes are merged at the APP boundary. Joining without
 * tailwind-merge avoids deleting custom typography/color utilities that
 * depend on each consumer's own @theme configuration.
 */
export function joinClasses(...items: Array<string|false|null|undefined>):string {
  return items.filter(Boolean).join(" ");
}
